#![forbid(unsafe_code)]

use std::{
    borrow::Cow,
    collections::{BTreeMap, BTreeSet, HashMap, HashSet, LinkedList, VecDeque},
    hash::{BuildHasher, Hash as StdHash},
    rc::Rc,
    sync::Arc,
};

pub use blake3;
pub use thoosa_digest_id_derive::DigestHash;
/// Generated by GPT. Makes the generated hashes stable across runs and resilient to field renames.
/// This stability is unnecessary here, since the hashes are used only as runtime IDs for stages
/// and are never persisted.

/// A deterministic, canonical content hash.
///
/// `update_digest` exists so nested values can contribute directly to the
/// parent's BLAKE3 stream without computing intermediate hashes.
pub trait DigestHash {
    #[doc(hidden)]
    fn update_digest(&self, hasher: &mut blake3::Hasher);

    fn blake3_hash(&self) -> blake3::Hash {
        let mut hasher = blake3::Hasher::new();

        // Domain separation for this hashing format.
        //
        // Never change this without considering it a new digest format.
        hasher.update(b"thoosa_digest_id:canonical-format:v1\0");

        self.update_digest(&mut hasher);

        hasher.finalize()
    }
}

/// Implementation details used by the derive macro.
///
/// This is public only because generated code lives in another crate.
#[doc(hidden)]
pub mod inner {
    use blake3::Hasher;

    pub const UNIT: u8 = 0x01;
    pub const BOOL: u8 = 0x02;

    pub const U8: u8 = 0x03;
    pub const U16: u8 = 0x04;
    pub const U32: u8 = 0x05;
    pub const U64: u8 = 0x06;
    pub const U128: u8 = 0x07;
    pub const USIZE: u8 = 0x08;

    pub const I8: u8 = 0x09;
    pub const I16: u8 = 0x0a;
    pub const I32: u8 = 0x0b;
    pub const I64: u8 = 0x0c;
    pub const I128: u8 = 0x0d;
    pub const ISIZE: u8 = 0x0e;

    pub const F32: u8 = 0x0f;
    pub const F64: u8 = 0x10;

    pub const CHAR: u8 = 0x11;
    pub const STR: u8 = 0x12;
    pub const BYTES: u8 = 0x13;

    pub const SEQUENCE: u8 = 0x20;
    pub const OPTION: u8 = 0x21;
    pub const RESULT: u8 = 0x22;
    pub const TUPLE: u8 = 0x23;
    pub const MAP: u8 = 0x24;
    pub const SET: u8 = 0x25;

    pub const STRUCT: u8 = 0x30;
    pub const FIELD: u8 = 0x31;
    pub const ENUM: u8 = 0x32;
    pub const VARIANT: u8 = 0x33;

    #[inline]
    pub fn tag(hasher: &mut Hasher, tag: u8) {
        hasher.update(&[tag]);
    }

    /// Canonical architecture-independent length encoding.
    #[inline]
    pub fn len(hasher: &mut Hasher, len: usize) {
        hasher.update(&(len as u128).to_le_bytes());
    }

    #[inline]
    pub fn framed_bytes(hasher: &mut Hasher, bytes: &[u8]) {
        len(hasher, bytes.len());
        hasher.update(bytes);
    }

    #[inline]
    pub fn begin_struct(hasher: &mut Hasher, type_tag: &str, field_count: usize) {
        tag(hasher, STRUCT);
        framed_bytes(hasher, type_tag.as_bytes());
        len(hasher, field_count);
    }

    #[inline]
    pub fn field(hasher: &mut Hasher, name: &str) {
        tag(hasher, FIELD);
        framed_bytes(hasher, name.as_bytes());
    }

    #[inline]
    pub fn begin_enum(hasher: &mut Hasher, type_tag: &str) {
        // Keep enums in a separate domain from structs even when a schema tag is accidentally reused.
        tag(hasher, ENUM);
        framed_bytes(hasher, type_tag.as_bytes());
    }

    #[inline]
    pub fn variant(hasher: &mut Hasher, name: &str, field_count: usize) {
        // The stable name makes variant declaration order irrelevant to the digest.
        tag(hasher, VARIANT);
        framed_bytes(hasher, name.as_bytes());
        len(hasher, field_count);
    }
}

// -------------------------------------------------------------------------
// Primitive types
// -------------------------------------------------------------------------

impl DigestHash for () {
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        inner::tag(hasher, inner::UNIT);
    }
}

impl DigestHash for bool {
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        inner::tag(hasher, inner::BOOL);
        hasher.update(&[*self as u8]);
    }
}

macro_rules! impl_integer {
    ($ty:ty, $tag:expr) => {
        impl DigestHash for $ty {
            fn update_digest(&self, hasher: &mut blake3::Hasher) {
                inner::tag(hasher, $tag);
                hasher.update(&self.to_le_bytes());
            }
        }
    };
}

impl_integer!(u8, inner::U8);
impl_integer!(u16, inner::U16);
impl_integer!(u32, inner::U32);
impl_integer!(u64, inner::U64);
impl_integer!(u128, inner::U128);

impl_integer!(i8, inner::I8);
impl_integer!(i16, inner::I16);
impl_integer!(i32, inner::I32);
impl_integer!(i64, inner::I64);
impl_integer!(i128, inner::I128);

impl DigestHash for usize {
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        inner::tag(hasher, inner::USIZE);

        // Avoid target-pointer-width-dependent byte encoding.
        hasher.update(&(*self as u128).to_le_bytes());
    }
}

impl DigestHash for isize {
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        inner::tag(hasher, inner::ISIZE);

        hasher.update(&(*self as i128).to_le_bytes());
    }
}

// -------------------------------------------------------------------------
// Floating point
// -------------------------------------------------------------------------

#[inline]
fn canonical_f32_bits(value: f32) -> u32 {
    if value == 0.0 {
        // Makes -0.0 and +0.0 identical.
        0
    } else if value.is_nan() {
        // All NaN payloads/signs become one canonical NaN.
        0x7fc0_0000
    } else {
        value.to_bits()
    }
}

#[inline]
fn canonical_f64_bits(value: f64) -> u64 {
    if value == 0.0 {
        0
    } else if value.is_nan() {
        0x7ff8_0000_0000_0000
    } else {
        value.to_bits()
    }
}

impl DigestHash for f32 {
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        inner::tag(hasher, inner::F32);

        hasher.update(&canonical_f32_bits(*self).to_le_bytes());
    }
}

impl DigestHash for f64 {
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        inner::tag(hasher, inner::F64);

        hasher.update(&canonical_f64_bits(*self).to_le_bytes());
    }
}

// -------------------------------------------------------------------------
// Strings / char
// -------------------------------------------------------------------------

impl DigestHash for char {
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        inner::tag(hasher, inner::CHAR);
        hasher.update(&(*self as u32).to_le_bytes());
    }
}

impl DigestHash for str {
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        inner::tag(hasher, inner::STR);
        inner::framed_bytes(hasher, self.as_bytes());
    }
}

impl DigestHash for String {
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        <str as DigestHash>::update_digest(self.as_str(), hasher);
    }
}

// -------------------------------------------------------------------------
// Transparent wrappers
// -------------------------------------------------------------------------

impl<T> DigestHash for &T
where
    T: DigestHash + ?Sized,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        <T as DigestHash>::update_digest(*self, hasher);
    }
}

impl<T> DigestHash for Box<T>
where
    T: DigestHash + ?Sized,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        <T as DigestHash>::update_digest(self.as_ref(), hasher);
    }
}

impl<T> DigestHash for Arc<T>
where
    T: DigestHash + ?Sized,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        <T as DigestHash>::update_digest(self.as_ref(), hasher);
    }
}

impl<T> DigestHash for Rc<T>
where
    T: DigestHash + ?Sized,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        <T as DigestHash>::update_digest(self.as_ref(), hasher);
    }
}

impl<T> DigestHash for Cow<'_, T>
where
    T: DigestHash + ToOwned + ?Sized,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        <T as DigestHash>::update_digest(self.as_ref(), hasher);
    }
}

// -------------------------------------------------------------------------
// Sequences
// -------------------------------------------------------------------------

fn update_sequence<'a, T, I>(hasher: &mut blake3::Hasher, len: usize, values: I)
where
    T: DigestHash + 'a,
    I: IntoIterator<Item = &'a T>,
{
    inner::tag(hasher, inner::SEQUENCE);
    inner::len(hasher, len);

    for value in values {
        <T as DigestHash>::update_digest(value, hasher);
    }
}

impl<T> DigestHash for [T]
where
    T: DigestHash,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        update_sequence(hasher, self.len(), self.iter());
    }
}

impl<T> DigestHash for Vec<T>
where
    T: DigestHash,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        <[T] as DigestHash>::update_digest(self.as_slice(), hasher);
    }
}

impl<T, const N: usize> DigestHash for [T; N]
where
    T: DigestHash,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        <[T] as DigestHash>::update_digest(self.as_slice(), hasher);
    }
}

impl<T> DigestHash for VecDeque<T>
where
    T: DigestHash,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        update_sequence(hasher, self.len(), self.iter());
    }
}

impl<T> DigestHash for LinkedList<T>
where
    T: DigestHash,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        update_sequence(hasher, self.len(), self.iter());
    }
}

// -------------------------------------------------------------------------
// Option / Result
// -------------------------------------------------------------------------

impl<T> DigestHash for Option<T>
where
    T: DigestHash,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        inner::tag(hasher, inner::OPTION);

        match self {
            None => {
                hasher.update(&[0]);
            }

            Some(value) => {
                hasher.update(&[1]);
                <T as DigestHash>::update_digest(value, hasher);
            }
        }
    }
}

impl<T, E> DigestHash for Result<T, E>
where
    T: DigestHash,
    E: DigestHash,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        inner::tag(hasher, inner::RESULT);

        match self {
            Ok(value) => {
                hasher.update(&[0]);
                <T as DigestHash>::update_digest(value, hasher);
            }

            Err(error) => {
                hasher.update(&[1]);
                <E as DigestHash>::update_digest(error, hasher);
            }
        }
    }
}

// -------------------------------------------------------------------------
// Tuples
// -------------------------------------------------------------------------

macro_rules! impl_tuple {
    (
        $len:expr;
        $( $T:ident : $index:tt ),+
    ) => {
        impl<$($T),+> DigestHash for ($($T,)+)
        where
            $($T: DigestHash),+
        {
            fn update_digest(
                &self,
                hasher: &mut blake3::Hasher,
            ) {
                inner::tag(
                    hasher,
                    inner::TUPLE,
                );

                inner::len(hasher, $len);

                $(
                    <$T as DigestHash>::update_digest(
                        &self.$index,
                        hasher,
                    );
                )+
            }
        }
    };
}

impl_tuple!(1; A:0);
impl_tuple!(2; A:0, B:1);
impl_tuple!(3; A:0, B:1, C:2);
impl_tuple!(4; A:0, B:1, C:2, D:3);
impl_tuple!(5; A:0, B:1, C:2, D:3, E:4);
impl_tuple!(6; A:0, B:1, C:2, D:3, E:4, F:5);
impl_tuple!(7; A:0, B:1, C:2, D:3, E:4, F:5, G:6);
impl_tuple!(8; A:0, B:1, C:2, D:3, E:4, F:5, G:6, H:7);

// -------------------------------------------------------------------------
// Maps / sets
// -------------------------------------------------------------------------

#[inline]
fn digest_bytes<T>(value: &T) -> [u8; 32]
where
    T: DigestHash + ?Sized,
{
    *DigestHash::blake3_hash(value).as_bytes()
}

fn update_map<'a, K, V, I>(hasher: &mut blake3::Hasher, len: usize, entries: I)
where
    K: DigestHash + 'a,
    V: DigestHash + 'a,
    I: IntoIterator<Item = (&'a K, &'a V)>,
{
    // HashMap iteration order is not stable.
    //
    // Convert each entry to fixed-size canonical digests and sort.
    let mut entries: Vec<([u8; 32], [u8; 32])> = entries.into_iter().map(|(key, value)| (digest_bytes(key), digest_bytes(value))).collect();

    entries.sort_unstable();

    inner::tag(hasher, inner::MAP);
    inner::len(hasher, len);

    for (key, value) in entries {
        hasher.update(&key);
        hasher.update(&value);
    }
}

fn update_set<'a, T, I>(hasher: &mut blake3::Hasher, len: usize, values: I)
where
    T: DigestHash + 'a,
    I: IntoIterator<Item = &'a T>,
{
    let mut values: Vec<[u8; 32]> = values.into_iter().map(digest_bytes).collect();

    values.sort_unstable();

    inner::tag(hasher, inner::SET);
    inner::len(hasher, len);

    for value in values {
        hasher.update(&value);
    }
}

impl<K, V> DigestHash for BTreeMap<K, V>
where
    K: DigestHash + Ord,
    V: DigestHash,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        update_map(hasher, self.len(), self.iter());
    }
}

impl<K, V, S> DigestHash for HashMap<K, V, S>
where
    K: DigestHash + Eq + StdHash,
    V: DigestHash,
    S: BuildHasher,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        update_map(hasher, self.len(), self.iter());
    }
}

impl<T> DigestHash for BTreeSet<T>
where
    T: DigestHash + Ord,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        update_set(hasher, self.len(), self.iter());
    }
}

impl<T, S> DigestHash for HashSet<T, S>
where
    T: DigestHash + Eq + StdHash,
    S: BuildHasher,
{
    fn update_digest(&self, hasher: &mut blake3::Hasher) {
        update_set(hasher, self.len(), self.iter());
    }
}

// -------------------------------------------------------------------------
// Custom field encoders
// -------------------------------------------------------------------------

/// Helpers usable with `#[digest(with = "...")]`.
pub mod with {
    use crate::{DigestHash, inner};

    /// Hash an f32 by its exact IEEE-754 bit representation.
    ///
    /// Unlike the normal `DigestHash for f32`:
    ///
    /// * +0.0 != -0.0
    /// * distinct NaN payloads remain distinct
    pub fn f32_bits(value: &f32, hasher: &mut blake3::Hasher) {
        inner::tag(hasher, inner::F32);

        hasher.update(&value.to_bits().to_le_bytes());
    }

    pub fn f64_bits(value: &f64, hasher: &mut blake3::Hasher) {
        inner::tag(hasher, inner::F64);

        hasher.update(&value.to_bits().to_le_bytes());
    }

    /// Efficiently hash byte buffers as a blob rather than as a sequence
    /// of individually tagged u8 values.
    pub fn bytes<T>(value: &T, hasher: &mut blake3::Hasher)
    where
        T: AsRef<[u8]> + ?Sized,
    {
        inner::tag(hasher, inner::BYTES);

        inner::framed_bytes(hasher, value.as_ref());
    }

    /// Example helper useful from custom encoders.
    pub fn as_digest<T>(value: &T, hasher: &mut blake3::Hasher)
    where
        T: DigestHash + ?Sized,
    {
        T::update_digest(value, hasher);
    }
}
